mapper.select:
select
    t.id,
    t.org_id as orgId,
    t.event_code as eventCode,
    t.event_name as eventName,
    t.biz_pid as bizPid,
    t.template_id as templateId,
    t.status,
    st.template_name as templateName
from sms_autosend_event t left join sms_template_set st on t.template_id=st.id

    st.template_status = 1

    and t.id = #{queryForm.id}


    and t.status = #{queryForm.status}


    and t.org_id = #{queryForm.orgId}


    and t.event_code = #{queryForm.eventCode}


    and t.bizPid = #{queryForm.bizPid}
